void enQueue(int value) {
    if (rear == SIZE - 1) {
        printf("Queue is Full!\n");
        return;
    }
    if (front == -1) front = 0;
    items[++rear] = value;
}

int deQueue() {
    if (front == -1 || front > rear) {
        printf("Queue is Empty!\n");
        return -1;
    }
    return items[front++];
}

