import time
from functools import wraps

def time_it(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        start = time.time()
        result = func(*args, **kwargs)
        duration = time.time() - start
        print(f"{func.__name__} took {duration:.6f}s")
        return result
    return wrapper

@time_it
def compute():
    return sum(i * i for i in range(100000))

