void reverseArray(int a[], int n) {
    int l = 0, r = n - 1;
    while(l < r) {
        int t = a[l]; a[l++] = a[r]; a[r--] = t;
    }
}

void findMinMax(int a[], int n, int *min, int *max) {
    *min = *max = a[0];
    for(int i = 1; i < n; i++) {
        if (a[i] < *min) *min = a[i];
        if (a[i] > *max) *max = a[i];
    }
}

